// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this) && actor != address(c));
        amount = bound(amount, 1, type(uint256).max / 4);

        // first deposit/withdraw cycle
        vm.deal(actor, amount * 2);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        bool ok1;
        try c.withdrawAll() { ok1 = true; } catch { ok1 = false; }

        // redeposit and withdraw again: the lock must have been released
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        bool ok2;
        try c.withdrawAll() { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && ok2 && address(c).balance == 0);
    }
}
